  1: //! Findings: `findings.json`, the finding lifecycle and ratings.
  2: //!
  3: //! Mirrors the stored record `codex-findings.ps1` keeps (README "Findings: ids, status,
  4: //! ratings"): the id `F<NN>-<k>` (`NN` the handoff number of the reply that raised it,
  5: //! `k` its 1-based position in that reply's `findings[]`), the tracked `status`, the
  6: //! severity, locations, the reviewer's claim/trigger/evidence, `supersedes`/`superseded_by`
  7: //! bookkeeping, `source`, an append-only `history[]` (one entry per status change) and
  8: //! `reviewer_checks[]` (one entry per later reply that reported on it). Field order matches
  9: //! the on-disk record and is preserved by [`crate::ps_json`].
 10: //!
 11: //! [`transition`] is the pure status-change rule (README): `verified` requires evidence, a
 12: //! `rejected` and a reopen (`-> proposed` from a non-`proposed` state) require a note, and
 13: //! `superseded` requires neither; any status may follow any other. Acceptance test:
 14: //! `tests/formats.rs` round-trips the real `.collab/c3-design/findings.json` byte-for-byte.
 15: 
 16: use serde::{Deserialize, Serialize};
 17: use serde_json::Value;
 18: 
 19: use crate::ps_json;
 20: 
 21: /// The whole `findings.json` document.
 22: #[derive(Debug, Clone, Serialize, Deserialize)]
 23: pub struct FindingsFile {
 24:     pub task_id: String,
 25:     pub findings: Vec<Finding>,
 26:     pub ratings: Vec<Rating>,
 27: }
 28: 
 29: /// The tracked lifecycle status of a finding.
 30: #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
 31: #[serde(rename_all = "lowercase")]
 32: pub enum FindingStatus {
 33:     Proposed,
 34:     Implemented,
 35:     Verified,
 36:     Rejected,
 37:     Wontfix,
 38:     Superseded,
 39: }
 40: 
 41: impl FindingStatus {
 42:     /// The on-disk token (`proposed`, ...).
 43:     pub fn as_str(self) -> &'static str {
 44:         match self {
 45:             FindingStatus::Proposed => "proposed",
 46:             FindingStatus::Implemented => "implemented",
 47:             FindingStatus::Verified => "verified",
 48:             FindingStatus::Rejected => "rejected",
 49:             FindingStatus::Wontfix => "wontfix",
 50:             FindingStatus::Superseded => "superseded",
 51:         }
 52:     }
 53: }
 54: 
 55: /// One stored finding.
 56: #[derive(Debug, Clone, Serialize, Deserialize)]
 57: pub struct Finding {
 58:     pub id: String,
 59:     pub status: FindingStatus,
 60:     /// `blocker | major | minor | note`.
 61:     pub severity: String,
 62:     pub locations: Vec<Location>,
 63:     pub claim: String,
 64:     pub trigger: String,
 65:     pub evidence: Vec<Evidence>,
 66:     pub verification: String,
 67:     pub remedy: String,
 68:     /// Ids this finding supersedes.
 69:     pub supersedes: Vec<Value>,
 70:     /// Ids that superseded this finding (filled on the OLD finding; bookkeeping).
 71:     pub superseded_by: Vec<Value>,
 72:     pub source: Source,
 73:     pub history: Vec<HistoryEvent>,
 74:     pub reviewer_checks: Vec<ReviewerCheck>,
 75: }
 76: 
 77: /// A code location; `line` is `null` when unknown.
 78: #[derive(Debug, Clone, Serialize, Deserialize)]
 79: pub struct Location {
 80:     pub path: String,
 81:     pub line: Option<i64>,
 82: }
 83: 
 84: /// A piece of evidence the reviewer cited.
 85: #[derive(Debug, Clone, Serialize, Deserialize)]
 86: pub struct Evidence {
 87:     /// `read-code | ran-command | inferred | assumed`.
 88:     pub kind: String,
 89:     pub reference: String,
 90:     pub observation: String,
 91: }
 92: 
 93: /// Where the finding came from.
 94: #[derive(Debug, Clone, Serialize, Deserialize)]
 95: pub struct Source {
 96:     pub consult: i64,
 97:     pub reply: String,
 98:     pub thread: String,
 99:     pub base_commit: String,
100:     pub tree_sha256: String,
101: }
102: 
103: /// One append-only status-change record.
104: #[derive(Debug, Clone, Serialize, Deserialize)]
105: pub struct HistoryEvent {
106:     pub when: String,
107:     pub status: FindingStatus,
108:     pub by: String,
109:     pub note: String,
110:     pub evidence: String,
111:     pub base_commit: String,
112:     pub tree_sha256: String,
113: }
114: 
115: /// One later reply's report on a finding (the reviewer's own `fixed`/`still-open`/
116: /// `not-checked`, never the tracked status).
117: #[derive(Debug, Clone, Serialize, Deserialize)]
118: pub struct ReviewerCheck {
119:     pub consult: i64,
120:     pub when: String,
121:     pub status: String,
122:     pub note: String,
123:     pub base_commit: String,
124:     pub tree_sha256: String,
125: }
126: 
127: /// A coordinator usefulness mark, copied from the ledger entry so it survives pruning.
128: #[derive(Debug, Clone, Serialize, Deserialize)]
129: pub struct Rating {
130:     pub n: i64,
131:     pub consult_id: String,
132:     pub lineage: String,
133:     pub provider: String,
134:     pub model: String,
135:     pub purpose: String,
136:     /// `yes | partly | no`.
137:     pub useful: String,
138:     pub note: String,
139:     pub when: String,
140: }
141: 
142: /// Why a status change was refused.
143: #[derive(Debug, Clone, PartialEq, Eq)]
144: pub enum TransitionError {
145:     /// `verified` needs `-Evidence`.
146:     EvidenceRequired,
147:     /// `rejected` needs `-Note`.
148:     NoteRequiredReject,
149:     /// A reopen (`-> proposed` from a non-`proposed` state) needs `-Note`.
150:     NoteRequiredReopen,
151: }
152: 
153: impl std::fmt::Display for TransitionError {
154:     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
155:         match self {
156:             TransitionError::EvidenceRequired => write!(
157:                 f,
158:                 "verified requires -Evidence (what you ran, not that you believe it)"
159:             ),
160:             TransitionError::NoteRequiredReject => write!(f, "rejected requires -Note"),
161:             TransitionError::NoteRequiredReopen => {
162:                 write!(f, "reopening a finding (-Status proposed) requires -Note")
163:             }
164:         }
165:     }
166: }
167: 
168: impl std::error::Error for TransitionError {}
169: 
170: /// The status-transition rule (README). Any status may follow any other; the gates are:
171: /// `verified` requires non-empty `evidence`; `rejected` requires a non-empty `note`; a
172: /// reopen (`to == proposed` while `from != proposed`) requires a non-empty `note`;
173: /// `superseded` requires neither. `note`/`evidence` are the trimmed argument values.
174: pub fn transition(
175:     from: FindingStatus,
176:     to: FindingStatus,
177:     note: &str,
178:     evidence: &str,
179: ) -> Result<(), TransitionError> {
180:     match to {
181:         FindingStatus::Verified if evidence.trim().is_empty() => {
182:             Err(TransitionError::EvidenceRequired)
183:         }
184:         FindingStatus::Rejected if note.trim().is_empty() => {
185:             Err(TransitionError::NoteRequiredReject)
186:         }
187:         FindingStatus::Proposed if from != FindingStatus::Proposed && note.trim().is_empty() => {
188:             Err(TransitionError::NoteRequiredReopen)
189:         }
190:         _ => Ok(()),
191:     }
192: }
193: 
194: /// `F<NN>-<k>` for a reply's handoff number `nn` and 1-based finding position `k`.
195: pub fn finding_id(nn: u32, k: usize) -> String {
196:     format!("F{nn:02}-{k}")
197: }
198: 
199: impl FindingsFile {
200:     /// Parse `findings.json` bytes.
201:     pub fn read(bytes: &[u8]) -> Result<Self, serde_json::Error> {
202:         serde_json::from_slice(bytes)
203:     }
204: 
205:     /// Serialize to the exact on-disk byte stream `Write-JsonFile` would produce.
206:     pub fn to_bytes(&self) -> Result<Vec<u8>, serde_json::Error> {
207:         ps_json::to_ps_json_bytes(self)
208:     }
209: }
