211: #[cfg(test)]
212: mod tests {
213:     use super::*;
214:     use FindingStatus::*;
215: 
216:     #[test]
217:     fn verified_needs_evidence() {
218:         assert_eq!(
219:             transition(Implemented, Verified, "", ""),
220:             Err(TransitionError::EvidenceRequired)
221:         );
222:         assert!(transition(Implemented, Verified, "", "ran cargo test: 21 passed").is_ok());
223:     }
224: 
225:     #[test]
226:     fn rejected_needs_note() {
227:         assert_eq!(
228:             transition(Proposed, Rejected, "", ""),
229:             Err(TransitionError::NoteRequiredReject)
230:         );
231:         assert!(transition(Proposed, Rejected, "not a real bug", "").is_ok());
232:     }
233: 
234:     #[test]
235:     fn reopen_needs_note_but_superseded_does_not() {
236:         assert_eq!(
237:             transition(Verified, Proposed, "", ""),
238:             Err(TransitionError::NoteRequiredReopen)
239:         );
240:         assert!(transition(Verified, Proposed, "regressed", "").is_ok());
241:         // proposed -> proposed is not a reopen.
242:         assert!(transition(Proposed, Proposed, "", "").is_ok());
243:         // superseded requires neither.
244:         assert!(transition(Verified, Superseded, "", "").is_ok());
245:     }
246: 
247:     #[test]
248:     fn id_format() {
249:         assert_eq!(finding_id(2, 1), "F02-1");
250:         assert_eq!(finding_id(15, 4), "F15-4");
251:         assert_eq!(finding_id(100, 3), "F100-3");
252:     }
253: }

  1: //! The evidence store: the files under `.collab/<task>/`, their locks and the commit
  2: //! write order.
  3: //!
  4: //! Mirrors `codex-consult-common.ps1`: the ownership lock `.consult.lock` and the commit
  5: //! lock `.consult.write.lock` (each a permanent file *owned by holding it open*, released
  6: //! when the handle closes - `Enter-TaskLock`/`Enter-WriteLock`/`Exit-TaskLock`), the
  7: //! recovery record `.consult.pending.json` (a panel member: `.consult.pending-<NN>.json`,
  8: //! `New-PendingRecord`), the atomic replace (`Write-TextAtomic`/`Write-JsonFile`) and the
  9: //! commit sequence (`Enter-StoreCommit` -> re-read -> `Complete-StoreCommit`: findings.json
 10: //! then sessions.json -> remove the recovery record -> `Exit-StoreCommit`).
 11: //!
 12: //! Invariants encoded here (DESIGN Â§3, README "Write order and atomic stores"):
 13: //! - **Write order.** `.reply.json` (the byte-for-byte raw copy) is written first, before
 14: //!   the lock; then, under `.consult.write.lock`, the rendered `.md`, `findings.json`,
 15: //!   `sessions.json` (the commit point) and the removal of the recovery record - see
 16: //!   [`COMMIT_WRITE_ORDER`].
 17: //! - **Re-read under the lock.** Every writer re-reads both stores under the write lock and
 18: //!   applies only its own delta, so no concurrent commit is lost.
 19: //! - **Lock = an open handle.** The lock is owned by holding the file open, never by its
 20: //!   contents; the record inside is informational (who holds it). Releasing = closing.
 21: //! - **Atomic replace.** A store is written to a temp file in the same directory, flushed,
 22: //!   and renamed over the store in one step (`std::fs::rename`, which replaces on both
 23: //!   Windows and Unix).
 24: 
 25: use std::fs::{self, File, OpenOptions};
 26: use std::io::{self, Write};
 27: use std::path::{Path, PathBuf};
 28: 
 29: use serde::{Deserialize, Serialize};
 30: use serde_json::Value;
 31: 
 32: use crate::findings::FindingsFile;
 33: use crate::ledger::{LedgerEntry, SessionsFile};
 34: use crate::ps_json;
 35: 
 36: /// The ownership lock file name.
 37: pub const OWNERSHIP_LOCK: &str = ".consult.lock";
 38: /// The commit (write) lock file name.
 39: pub const WRITE_LOCK: &str = ".consult.write.lock";
 40: /// The single-run recovery record file name.
 41: pub const PENDING: &str = ".consult.pending.json";
 42: 
 43: /// The state of an interrupted run's recovery record (`$script:PendingStates`).
 44: #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
 45: #[serde(rename_all = "lowercase")]
 46: pub enum PendingState {
 47:     Reserved,
 48:     Launching,
 49:     Running,
 50:     Survivors,
 51:     Committing,
 52: }
 53: 
 54: /// The informational content of `.consult.lock` / `.consult.write.lock`. Written compact
 55: /// (one line) plus a trailing `\n`; nothing recoverable lives here.
 56: #[derive(Debug, Clone, Serialize, Deserialize)]
 57: pub struct LockRecord {
 58:     pub pid: u32,
 59:     /// The process start time as an ISO string (used with `pid` to tell a stale lock's
 60:     /// owner from a live one).
 61:     pub start_time: String,
 62:     pub host: String,
 63:     pub task: String,
 64:     pub started: String,
 65:     /// Present only for a panel run.
 66:     #[serde(skip_serializing_if = "Option::is_none", default)]
 67:     pub panel: Option<Value>,
 68: }
 69: 
 70: impl LockRecord {
 71:     /// The compact, newline-terminated bytes the bridge writes into a lock file.
 72:     pub fn to_bytes(&self) -> Result<Vec<u8>, serde_json::Error> {
 73:         let mut s = serde_json::to_string(self)?;
 74:         s.push('\n');
 75:         Ok(s.into_bytes())
 76:     }
 77: }
 78: 
 79: /// The recovery record (`New-PendingRecord`). Field order matches the literal. Written
 80: /// with the same pretty formatter as the stores ([`ps_json`]).
 81: #[derive(Debug, Clone, Serialize, Deserialize)]
 82: pub struct PendingRecord {
 83:     pub state: PendingState,
 84:     pub n: i64,
 85:     pub nn: String,
 86:     pub reply: String,
 87:     pub events: String,
 88:     pub consult_id: String,
 89:     pub started: String,
 90:     pub pid: u32,
 91:     pub start_time: String,
 92:     pub host: String,
 93:     pub launcher: String,
 94:     pub engine: String,
 95:     pub child_pid: Option<u32>,
 96:     pub child_start_time: String,
 97:     /// `{pid, start_time, name}` entries the kill could see; kept raw.
 98:     pub survivors: Vec<Value>,
 99:     pub note: String,
100:     /// Present only for a panel member's record.
101:     #[serde(skip_serializing_if = "Option::is_none", default)]
102:     pub panel: Option<Value>,
103: }
104: 
105: impl PendingRecord {
106:     /// Serialize with the PowerShell-5.1 pretty formatter (as `Write-PendingFile`).
107:     pub fn to_bytes(&self) -> Result<Vec<u8>, serde_json::Error> {
108:         ps_json::to_ps_json_bytes(self)
109:     }
110: }
111: 
112: /// One step of the commit sequence, in order. The variants before [`WriteStep::TakeWriteLock`]
113: /// happen without the lock; the rest happen while it is held; releasing is implicit at the
114: /// end. This is the documented, machine-checkable encoding of the write order.
115: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
116: pub enum WriteStep {
117:     /// `.reply.json` - the byte-for-byte raw copy, before anything parses it.
118:     RawReply,
119:     /// Take `.consult.write.lock` (backoff up to 60 s) and mark the record `committing`.
120:     TakeWriteLock,
121:     /// Re-read `findings.json` and `sessions.json` under the lock.
122:     ReReadStores,
123:     /// The rendered handoff `.md`.
124:     HandoffMarkdown,
125:     /// `findings.json` (this run's delta applied to the fresh store).
126:     Findings,
127:     /// `sessions.json` - the entry inserted by `n`; THE commit point.
128:     Sessions,
129:     /// Remove (or keep, marked `committing`) the recovery record.
130:     RemoveRecoveryRecord,
131:     /// Close the write-lock handle.
132:     ReleaseWriteLock,
133: }
134: 
135: /// The commit write order (README "Write order and atomic stores"; wave-21 lock discipline).
136: pub const COMMIT_WRITE_ORDER: [WriteStep; 8] = [
137:     WriteStep::RawReply,
138:     WriteStep::TakeWriteLock,
139:     WriteStep::ReReadStores,
140:     WriteStep::HandoffMarkdown,
141:     WriteStep::Findings,
142:     WriteStep::Sessions,
143:     WriteStep::RemoveRecoveryRecord,
144:     WriteStep::ReleaseWriteLock,
145: ];
146: 
147: /// A held task lock: the OS file handle. Dropping it releases the lock (closes the handle),
148: /// exactly as `Exit-TaskLock` does; the file itself stays on disk.
149: #[derive(Debug)]
150: pub struct TaskLock {
151:     pub path: PathBuf,
152:     _file: File,
153: }
154: 
155: /// The evidence store contract (DESIGN Â§4). One implementation, [`FilesStore`].
156: pub trait EvidenceStore {
157:     /// `<collab>/<task>` - the task directory that holds the stores, locks and handoffs.
158:     fn task_dir(&self, task: &str) -> PathBuf;
159: 
160:     /// Parse `sessions.json`; `None` when it does not exist.
161:     fn read_sessions(&self, task: &str) -> io::Result<Option<SessionsFile>>;
162: 
163:     /// Parse `findings.json`; `None` when it does not exist.
164:     fn read_findings(&self, task: &str) -> io::Result<Option<FindingsFile>>;
165: 
166:     /// Read every recovery record of the task (`.consult.pending.json` first, then the
167:     /// panel members' `.consult.pending-<NN>.json` by name). The read side of
168:     /// `Read-TaskPendingRecords`; judging which are still active by process liveness is a
169:     /// runtime concern (M3).
170:     fn recover_pending(&self, task: &str) -> io::Result<Vec<PendingRecord>>;
171: 
172:     /// The next handoff number `NN`: greater than every `<NN>-` handoff file, every finding
173:     /// id `F<NN>`, and every recovery record's `nn` (`Get-NextNumbers`, the `NN` half).
174:     fn next_handoff_number(&self, task: &str) -> io::Result<u32>;
175: 
176:     /// Take the ownership lock `.consult.lock`, holding the handle open for the run.
177:     fn take_task_lock(&self, task: &str, record: &LockRecord) -> io::Result<TaskLock>;
178: 
179:     /// Write the recovery record atomically.
180:     fn write_pending(&self, task: &str, record: &PendingRecord) -> io::Result<()>;
181: 
182:     /// Commit a consultation under the write lock, following [`COMMIT_WRITE_ORDER`]:
183:     /// re-read the stores, apply this run's delta (insert `entry` by `n`, set `findings`),
184:     /// write the handoff `files`, write `findings.json` then `sessions.json` atomically,
185:     /// then remove the recovery record. Returns the write lock's wait in milliseconds.
186:     fn commit(
187:         &self,
188:         task: &str,
189:         entry: LedgerEntry,
190:         findings: Option<FindingsFile>,
191:         files: &[(PathBuf, Vec<u8>)],
192:     ) -> io::Result<u64>;
193: }
194: 
195: /// The files-on-disk store. `collab` is the collaboration root (default `.collab`).
196: #[derive(Debug, Clone)]
197: pub struct FilesStore {
198:     pub collab: PathBuf,
199: }
200: 
201: impl FilesStore {
202:     pub fn new(collab: impl Into<PathBuf>) -> Self {
203:         FilesStore {
204:             collab: collab.into(),
205:         }
206:     }
207: }
208: 
209: /// Atomic replace: write to a temp file in the same directory, flush, rename over `path`.
210: /// `std::fs::rename` replaces an existing destination on both Windows and Unix. Mirrors
211: /// `Write-TextAtomic`.
212: pub fn write_text_atomic(path: &Path, bytes: &[u8]) -> io::Result<()> {
213:     let dir = path.parent().unwrap_or_else(|| Path::new("."));
214:     let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("store");
215:     let tmp = dir.join(format!(".{name}.{}.tmp", uuid_like()));
216:     {
217:         let mut f = OpenOptions::new().write(true).create_new(true).open(&tmp)?;
218:         f.write_all(bytes)?;
219:         f.flush()?;
220:         f.sync_all()?;
221:     }
222:     fs::rename(&tmp, path)
223: }
224: 
225: /// A cheap unique-ish suffix for temp file names (not a real UUID; only needs to avoid a
226: /// collision with a concurrent writer in the same directory).
227: fn uuid_like() -> String {
228:     use std::time::{SystemTime, UNIX_EPOCH};
229:     let nanos = SystemTime::now()
230:         .duration_since(UNIX_EPOCH)
231:         .map(|d| d.as_nanos())
232:         .unwrap_or(0);
233:     format!("{nanos:x}{:x}", std::process::id())
234: }
235: 
236: fn read_opt(path: &Path) -> io::Result<Option<Vec<u8>>> {
237:     match fs::read(path) {
238:         Ok(b) => Ok(Some(b)),
239:         Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(None),
240:         Err(e) => Err(e),
241:     }
242: }
243: 
244: fn map_err(e: serde_json::Error) -> io::Error {
245:     io::Error::new(io::ErrorKind::InvalidData, e)
246: }
247: 
248: impl EvidenceStore for FilesStore {
249:     fn task_dir(&self, task: &str) -> PathBuf {
250:         self.collab.join(task)
251:     }
252: 
253:     fn read_sessions(&self, task: &str) -> io::Result<Option<SessionsFile>> {
254:         match read_opt(&self.task_dir(task).join("sessions.json"))? {
255:             Some(b) => Ok(Some(SessionsFile::read(&b).map_err(map_err)?)),
256:             None => Ok(None),
257:         }
258:     }
259: 
260:     fn read_findings(&self, task: &str) -> io::Result<Option<FindingsFile>> {
261:         match read_opt(&self.task_dir(task).join("findings.json"))? {
262:             Some(b) => Ok(Some(FindingsFile::read(&b).map_err(map_err)?)),
263:             None => Ok(None),
264:         }
265:     }
266: 
267:     fn recover_pending(&self, task: &str) -> io::Result<Vec<PendingRecord>> {
268:         let dir = self.task_dir(task);
269:         let mut single: Option<PendingRecord> = None;
270:         let mut members: Vec<(String, PendingRecord)> = Vec::new();
271:         let entries = match fs::read_dir(&dir) {
272:             Ok(e) => e,
273:             Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
274:             Err(e) => return Err(e),
275:         };
276:         for ent in entries {
277:             let ent = ent?;
278:             let name = ent.file_name().to_string_lossy().to_string();
279:             let is_single = name.eq_ignore_ascii_case(PENDING);
280:             let is_member = name.starts_with(".consult.pending-") && name.ends_with(".json");
281:             if !is_single && !is_member {
282:                 continue;
283:             }
284:             let bytes = fs::read(ent.path())?;
285:             let rec: PendingRecord = serde_json::from_slice(&bytes).map_err(map_err)?;
286:             if is_single {
287:                 single = Some(rec);
288:             } else {
289:                 members.push((name, rec));
290:             }
291:         }
292:         members.sort_by_key(|(name, _)| name.to_lowercase());
293:         let mut out = Vec::new();
294:         if let Some(s) = single {
295:             out.push(s);
296:         }
297:         out.extend(members.into_iter().map(|(_, r)| r));
298:         Ok(out)
299:     }
300: 
301:     fn next_handoff_number(&self, task: &str) -> io::Result<u32> {
302:         let dir = self.task_dir(task);
303:         let mut max_nn: u32 = 0;
304:         // handoff files "<NN>-..." (two or more digits).
305:         if let Ok(entries) = fs::read_dir(dir.join("handoffs")) {
306:             for ent in entries.flatten() {
307:                 let name = ent.file_name().to_string_lossy().to_string();
308:                 if let Some(nn) = leading_number(&name) {
309:                     max_nn = max_nn.max(nn);
310:                 }
311:             }
312:         }
313:         // finding ids F<NN>-<k>.
314:         if let Some(f) = self.read_findings(task)? {
315:             for fd in &f.findings {
316:                 if let Some(nn) = finding_nn(&fd.id) {
317:                     max_nn = max_nn.max(nn);
318:                 }
319:             }
320:         }
321:         // recovery records' nn.
322:         for rec in self.recover_pending(task)? {
323:             if let Ok(nn) = rec.nn.parse::<u32>() {
324:                 max_nn = max_nn.max(nn);
325:             }
326:         }
327:         Ok(max_nn + 1)
328:     }
329: 
330:     fn take_task_lock(&self, task: &str, record: &LockRecord) -> io::Result<TaskLock> {
331:         let dir = self.task_dir(task);
332:         fs::create_dir_all(&dir)?;
333:         let path = dir.join(OWNERSHIP_LOCK);
334:         // Open (create if absent) and hold the handle. NOTE (M3): the bridge opens with
335:         // FileShare.Read on Windows / FileShare.None on Unix so a second run's exclusive
336:         // open fails fast; reproducing that exact share mode needs a platform open call.
337:         // Here we hold the handle open, which is the contract; the share flags are M3.
338:         let mut file = OpenOptions::new()
339:             .read(true)
340:             .write(true)
341:             .create(true)
342:             .truncate(false)
343:             .open(&path)?;
344:         let bytes = record.to_bytes().map_err(map_err)?;
345:         file.set_len(0)?;
346:         file.write_all(&bytes)?;
347:         file.flush()?;
348:         Ok(TaskLock { path, _file: file })
349:     }
350: 
351:     fn write_pending(&self, task: &str, record: &PendingRecord) -> io::Result<()> {
352:         let dir = self.task_dir(task);
353:         fs::create_dir_all(&dir)?;
354:         let path = dir.join(PENDING);
355:         write_text_atomic(&path, &record.to_bytes().map_err(map_err)?)
356:     }
357: 
358:     fn commit(
359:         &self,
360:         task: &str,
361:         entry: LedgerEntry,
362:         findings: Option<FindingsFile>,
363:         files: &[(PathBuf, Vec<u8>)],
364:     ) -> io::Result<u64> {
365:         let dir = self.task_dir(task);
366:         fs::create_dir_all(&dir)?;
367:         // (In a full runtime this holds .consult.write.lock across the whole sequence and
368:         // returns commit_wait_ms; here the lock acquisition/backoff is M3 - see
369:         // take_task_lock's note - and the ordered writes below ARE the encoded write order.)
370:         // ReReadStores: start from the fresh on-disk ledger, apply this run's delta.
371:         let mut sessions = self.read_sessions(task)?.unwrap_or_else(|| SessionsFile {
372:             task_id: task.to_string(),
373:             cwd: String::new(),
374:             codex: crate::ledger::LedgerBook {
375:                 tool: entry.reviewer.harness.clone(),
376:                 consults: Vec::new(),
377:             },
378:         });
379:         sessions.add_entry(entry);
380:         // HandoffMarkdown (and any other per-consultation files).
381:         for (rel, bytes) in files {
382:             let path = dir.join(rel);
383:             if let Some(parent) = path.parent() {
384:                 fs::create_dir_all(parent)?;
385:             }
386:             write_text_atomic(&path, bytes)?;
387:         }
388:         // Findings, then Sessions (the commit point).
389:         if let Some(f) = findings {
390:             write_text_atomic(&dir.join("findings.json"), &f.to_bytes().map_err(map_err)?)?;
391:         }
392:         write_text_atomic(
393:             &dir.join("sessions.json"),
394:             &sessions.to_bytes().map_err(map_err)?,
395:         )?;
396:         // RemoveRecoveryRecord.
397:         let pending = dir.join(PENDING);
398:         if pending.exists() {
399:             fs::remove_file(&pending)?;
400:         }
401:         Ok(0)
402:     }
403: }
