405: fn leading_number(name: &str) -> Option<u32> {
406:     let digits: String = name.chars().take_while(|c| c.is_ascii_digit()).collect();
407:     if digits.len() >= 2 && name[digits.len()..].starts_with('-') {
408:         digits.parse().ok()
409:     } else {
410:         None
411:     }
412: }
413: 
414: fn finding_nn(id: &str) -> Option<u32> {
415:     let rest = id.strip_prefix('F')?;
416:     let digits: String = rest.chars().take_while(|c| c.is_ascii_digit()).collect();
417:     digits.parse().ok()
418: }
