423: 
424:     #[test]
425:     fn write_order_is_the_documented_sequence() {
426:         assert_eq!(COMMIT_WRITE_ORDER[0], WriteStep::RawReply);
427:         assert_eq!(COMMIT_WRITE_ORDER[1], WriteStep::TakeWriteLock);
428:         // sessions.json is the commit point and comes after findings.json.
429:         let s = COMMIT_WRITE_ORDER
430:             .iter()
431:             .position(|x| *x == WriteStep::Sessions)
432:             .unwrap();
433:         let f = COMMIT_WRITE_ORDER
434:             .iter()
435:             .position(|x| *x == WriteStep::Findings)
436:             .unwrap();
437:         assert!(f < s, "findings.json is written before sessions.json");
438:         assert_eq!(
439:             *COMMIT_WRITE_ORDER.last().unwrap(),
440:             WriteStep::ReleaseWriteLock
441:         );
442:     }
