447:         assert_eq!(leading_number("100-x.md"), Some(100));
448:         assert_eq!(leading_number("9-x.md"), None); // needs two+ digits
449:         assert_eq!(finding_nn("F15-4"), Some(15));
450:         assert_eq!(finding_nn("F02-1"), Some(2));
451:     }
