105: impl PendingRecord {
106:     /// Serialize with the PowerShell-5.1 pretty formatter (as `Write-PendingFile`).
107:     pub fn to_bytes(&self) -> Result<Vec<u8>, serde_json::Error> {
108:         ps_json::to_ps_json_bytes(self)
