209: /// Atomic replace: write to a temp file in the same directory, flush, rename over `path`.
210: /// `std::fs::rename` replaces an existing destination on both Windows and Unix. Mirrors
211: /// `Write-TextAtomic`.
212: pub fn write_text_atomic(path: &Path, bytes: &[u8]) -> io::Result<()> {
213:     let dir = path.parent().unwrap_or_else(|| Path::new("."));
214:     let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("store");
215:     let tmp = dir.join(format!(".{name}.{}.tmp", uuid_like()));
216:     {
217:         let mut f = OpenOptions::new().write(true).create_new(true).open(&tmp)?;
218:         f.write_all(bytes)?;
219:         f.flush()?;
220:         f.sync_all()?;
221:     }
222:     fs::rename(&tmp, path)
223: }
224: 
225: /// A cheap unique-ish suffix for temp file names (not a real UUID; only needs to avoid a
226: /// collision with a concurrent writer in the same directory).
227: fn uuid_like() -> String {
228:     use std::time::{SystemTime, UNIX_EPOCH};
229:     let nanos = SystemTime::now()
230:         .duration_since(UNIX_EPOCH)
231:         .map(|d| d.as_nanos())
232:         .unwrap_or(0);
233:     format!("{nanos:x}{:x}", std::process::id())
234: }
