  1: //! The engine contract (DESIGN Â§4): one attempt of one reviewer, and the exact argv the
  2: //! plugin builds for the subprocess engines.
  3: //!
  4: //! An [`Engine`] reports its [`Capabilities`], plans the argv for a [`Request`]
  5: //! ([`Engine::plan`]), and - in M2b - runs a turn and continues a conversation
  6: //! ([`Engine::run`], [`Engine::continue_turn`], left as signatures here). The three
  7: //! subprocess engines wrap the CLIs exactly as `codex-consult.ps1` / `New-AgyArgv` /
  8: //! `New-MuseArgv` do: the prompt on stdin (codex, agy) or a prompt file (muse), every
  9: //! exec-level option BEFORE the `fork`/`resume` subcommand (codex), and `-` for stdin
 10: //! (codex). The `http` engine builds one OpenAI-compatible request from a reviewer pack
 11: //! instead of an argv (M7); its `plan` therefore returns [`EngineError::NoArgv`].
 12: //!
 13: //! Ids (DESIGN Â§4 "Identity"): [`ConsultationId`] is one brief + one reviewer;
 14: //! [`AttemptId`] is one engine call (a retry is a NEW attempt with the same inputs, no
 15: //! redraw); [`ConversationId`] is the engine thread for CLI engines, or a C3-owned
 16: //! transcript for `http` (whose continuation is replay: the retained pack plus the prior
 17: //! reply). `resume_supported` is reported per engine ([`Capabilities::resume`]).
 18: 
 19: use std::path::PathBuf;
 20: 
 21: use serde::{Deserialize, Serialize};
 22: 
 23: use crate::ledger::Usage;
 24: 
 25: /// The four engines (DESIGN Â§4). `codex` is the default.
 26: #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
 27: #[serde(rename_all = "lowercase")]
 28: pub enum EngineKind {
 29:     Codex,
 30:     Agy,
 31:     Muse,
 32:     Http,
 33: }
 34: 
 35: /// How a reviewer receives the reply schema.
 36: #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
 37: #[serde(rename_all = "kebab-case")]
 38: pub enum SchemaTransport {
 39:     /// Codex `--output-schema` / muse `--output-schema`.
 40:     OutputSchema,
 41:     /// agy `--json-schema` (a native structured-output request).
 42:     Native,
 43:     /// The schema is described in the prompt only.
 44:     PromptOnly,
 45: }
 46: 
 47: /// What an engine can do (DESIGN Â§4: `capabilities()`).
 48: #[derive(Debug, Clone)]
 49: pub struct Capabilities {
 50:     /// The engine keeps conversation threads (a reply can be resumed/forked).
 51:     pub threads: bool,
 52:     /// Forking a thread is supported (codex only).
 53:     pub fork: bool,
 54:     /// Resuming a thread is supported natively.
 55:     pub resume: bool,
 56:     /// The schema transports the engine accepts, in preference order.
 57:     pub schema_transport: Vec<SchemaTransport>,
 58:     /// The effort vocabulary label (`openai`, `model-tier`, `muse`, ...).
 59:     pub effort_vocabulary: &'static str,
 60:     /// The engine runs its reviewer in a read-only sandbox.
 61:     pub sandbox: bool,
 62:     /// The handoff/file prefix for this engine (`codex`, `agy`, `muse`, `http`).
 63:     pub file_prefix: &'static str,
 64: }
 65: 
 66: /// The capability table for an engine, from `$script:Engines` (and DESIGN Â§4 for `http`).
 67: pub fn capabilities(kind: EngineKind) -> Capabilities {
 68:     match kind {
 69:         EngineKind::Codex => Capabilities {
 70:             threads: true,
 71:             fork: true,
 72:             resume: true,
 73:             schema_transport: vec![SchemaTransport::OutputSchema, SchemaTransport::PromptOnly],
 74:             effort_vocabulary: "openai",
 75:             sandbox: true,
 76:             file_prefix: "codex",
 77:         },
 78:         EngineKind::Agy => Capabilities {
 79:             threads: true,
 80:             fork: false,
 81:             resume: true,
 82:             schema_transport: vec![SchemaTransport::Native, SchemaTransport::PromptOnly],
 83:             effort_vocabulary: "model-tier",
 84:             // agy --sandbox restricts the terminal only; the bridge's tree check enforces
 85:             // read-only. The capability is "runs read-only" as the bridge guarantees it.
 86:             sandbox: true,
 87:             file_prefix: "agy",
 88:         },
 89:         EngineKind::Muse => Capabilities {
 90:             threads: true,
 91:             fork: false,
 92:             resume: true,
 93:             schema_transport: vec![SchemaTransport::Native, SchemaTransport::PromptOnly],
 94:             effort_vocabulary: "muse",
 95:             sandbox: true,
 96:             file_prefix: "muse",
 97:         },
 98:         EngineKind::Http => Capabilities {
 99:             threads: false,
100:             fork: false,
101:             // Continuation is replay (the retained pack + the prior reply), not a native
102:             // thread resume; reported as unsupported.
103:             resume: false,
104:             schema_transport: vec![SchemaTransport::OutputSchema, SchemaTransport::PromptOnly],
105:             effort_vocabulary: "openai",
106:             // The http engine never receives tools (DESIGN Â§3 invariant 2).
107:             sandbox: false,
108:             file_prefix: "http",
109:         },
110:     }
111: }
