306: /// A subprocess engine (codex, agy or muse). Its [`Engine::plan`] reproduces the plugin's
307: /// argv byte for byte; [`Engine::run`]/[`Engine::continue_turn`] land in M2b.
308: #[derive(Debug, Clone)]
309: pub struct SubprocessEngine {
310:     pub kind: EngineKind,
311: }
312: 
313: impl SubprocessEngine {
314:     pub fn new(kind: EngineKind) -> Self {
315:         SubprocessEngine { kind }
316:     }
317: 
318:     fn plan_codex(&self, r: &Request) -> Result<Argv, EngineError> {
319:         // codex exec --sandbox <s> --color never --json [-m <model>]
320:         //   -c model_reasoning_effort="<e>" [-c model_provider="<p>"] [-c <extra>...]
321:         //   -o <tmp> [--output-schema <schema>] [fork|resume <thread>] -
322:         // Every exec-level option precedes the fork|resume subcommand; `-` is stdin.
323:         let mut a: Vec<String> = vec![
324:             "exec".into(),
325:             "--sandbox".into(),
326:             r.sandbox.clone(),
327:             "--color".into(),
328:             "never".into(),
329:             "--json".into(),
330:         ];
331:         if !r.model.is_empty() {
332:             a.push("-m".into());
333:             a.push(r.model.clone());
334:         }
335:         if let Some(e) = &r.effort {
336:             a.push("-c".into());
337:             a.push(format!("model_reasoning_effort=\"{e}\""));
338:         }
339:         if !r.provider.is_empty() {
340:             a.push("-c".into());
341:             a.push(format!("model_provider=\"{}\"", r.provider));
342:         }
343:         for item in &r.extra_config {
344:             a.push("-c".into());
345:             a.push(item.clone());
346:         }
347:         if let Some(o) = &r.output_last_message {
348:             a.push("-o".into());
349:             a.push(o.to_string_lossy().into_owned());
350:         }
351:         if let Some(s) = &r.schema_path {
352:             a.push("--output-schema".into());
353:             a.push(s.to_string_lossy().into_owned());
354:         }
355:         match &r.mode {
356:             Mode::New => {}
357:             Mode::Resume(t) => {
358:                 a.push("resume".into());
359:                 a.push(t.clone());
360:             }
361:             Mode::Fork(_t) => {
362:                 a.push("fork".into());
363:             }
364:         }
365:         a.push("-".into());
366:         Ok(Argv {
367:             command: "codex".into(),
368:             args: a,
369:         })
370:     }
371: 
372:     fn plan_agy(&self, r: &Request) -> Result<Argv, EngineError> {
373:         // -p= --input-format stream-json --output-format stream-json --model <m>
374:         //   [--json-schema <schema>] --print-timeout 0 --sandbox --disable-slash-commands
375:         //   [--conversation <thread>] [--effort <e>]
376:         if r.model.is_empty() {
377:             return Err(EngineError::MissingField("model"));
378:         }
379:         let mut a: Vec<String> = vec![
380:             "-p=".into(),
381:             "--input-format".into(),
382:             "stream-json".into(),
383:             "--output-format".into(),
384:             "stream-json".into(),
385:             "--model".into(),
386:             r.model.clone(),
387:         ];
388:         if let Some(s) = &r.schema_path {
389:             a.push("--json-schema".into());
390:             a.push(s.to_string_lossy().into_owned());
391:         }
392:         a.push("--print-timeout".into());
393:         a.push("0".into());
394:         a.push("--sandbox".into());
395:         a.push("--disable-slash-commands".into());
396:         if let Mode::Resume(t) = &r.mode {
397:             a.push("--conversation".into());
398:             a.push(t.clone());
399:         }
400:         if let Some(e) = &r.effort {
401:             a.push("--effort".into());
402:             a.push(e.clone());
403:         }
404:         Ok(Argv {
405:             command: "agy".into(),
406:             args: a,
407:         })
408:     }
409: 
410:     fn plan_muse(&self, r: &Request) -> Result<Argv, EngineError> {
411:         // exec --json --prompt-file <P> [--output-schema <S>] --model <m>
412:         //   [--reasoning-effort <e>] --no-foreign-personal-context --disable-web-tools
413:         //   --disable-write --disable-shell --approval-mode never [--max-model-steps <n>]
414:         //   [--session-id <thread>]
415:         let prompt_file = r
416:             .prompt_file
417:             .as_ref()
418:             .ok_or(EngineError::MissingField("prompt_file"))?;
419:         if r.model.is_empty() {
420:             return Err(EngineError::MissingField("model"));
421:         }
422:         let mut a: Vec<String> = vec![
423:             "exec".into(),
424:             "--json".into(),
425:             "--prompt-file".into(),
426:             prompt_file.to_string_lossy().into_owned(),
427:         ];
428:         if let Some(s) = &r.schema_path {
429:             a.push("--output-schema".into());
430:             a.push(s.to_string_lossy().into_owned());
431:         }
432:         a.push("--model".into());
433:         a.push(r.model.clone());
434:         if let Some(e) = &r.effort {
435:             if !e.trim().is_empty() {
436:                 a.push("--reasoning-effort".into());
437:                 a.push(e.clone());
438:             }
439:         }
440:         a.push("--no-foreign-personal-context".into());
441:         a.push("--disable-web-tools".into());
442:         a.push("--disable-write".into());
443:         a.push("--disable-shell".into());
444:         a.push("--approval-mode".into());
445:         a.push("never".into());
446:         if let Some(n) = r.max_model_steps {
447:             if n > 0 {
448:                 a.push("--max-model-steps".into());
449:                 a.push(n.to_string());
450:             }
451:         }
452:         if let Mode::Resume(t) = &r.mode {
453:             a.push("--session-id".into());
454:             a.push(t.clone());
455:         }
456:         Ok(Argv {
457:             command: "muse".into(),
458:             args: a,
459:         })
460:     }
461: }
