166:     #[test]
167:     fn colon_two_spaces_and_column_anchor() {
168:         let v = json!({"codex": {"tool": "x"}});
169:         let s = format_value_root(&v);
170:         // "codex" quoted len = 7; bracket at 0+4+7+3 = 14; child at 18.
171:         assert_eq!(
172:             s,
173:             "{\n    \"codex\":  {\n                  \"tool\":  \"x\"\n              }\n}"
174:         );
