  32: use sha2::{Digest, Sha256};
  33: 
  34: /// Lowercase hex SHA-256 of the bytes (`Get-Sha256Hex`).
  35: pub fn sha256_hex(bytes: &[u8]) -> String {
  36:     let mut h = Sha256::new();
  37:     h.update(bytes);
  38:     let out = h.finalize();
  39:     let mut s = String::with_capacity(out.len() * 2);
  40:     for b in out {
  41:         s.push_str(&format!("{b:02x}"));
  42:     }
  43:     s
  44: }
  45: 
  46: /// Collapse every run of whitespace to a single space and trim (`ConvertTo-OneLine`).
  47: pub fn one_line(text: &str) -> String {
  48:     let mut out = String::with_capacity(text.len());
  49:     let mut in_ws = false;
  50:     for c in text.chars() {
  51:         if c.is_whitespace() {
  52:             in_ws = true;
  53:         } else {
  54:             if in_ws && !out.is_empty() {
  55:                 out.push(' ');
  56:             }
  57:             in_ws = false;
  58:             out.push(c);
  59:         }
  60:     }
  61:     out
  62: }

