161: /// `Resolve-ReviewerIdentity`.
162: pub fn resolve_reviewer_identity(
163:     config: &CodexConfig,
164:     provider: &str,
165:     model: &str,
166:     openai_base_url: &str,
167:     engine: &str,
168:     launcher: &str,
169: ) -> ReviewerIdentity {
170:     let mut id = ReviewerIdentity::blank(&config.path);
171:     if !engine.is_empty() && engine != "codex" {
172:         return resolve_engine_identity(id, engine, provider, model, launcher);
173:     }
174:     let mut notes: Vec<String> = Vec::new();
175:     let mut infos: Vec<String> = Vec::new();
176:     let where_ = if !config.path.is_empty() {
177:         config.path.clone()
178:     } else {
179:         "(no Codex home)".to_string()
180:     };
181:     let file_reason = if config.exists && !config.ok {
182:         config.reason.clone()
183:     } else {
184:         String::new()
185:     };
186:     let top = if config.exists && config.ok {
187:         config.top()
188:     } else {
189:         None
190:     };
191:     let mut top_reason = file_reason.clone();
192:     if top_reason.is_empty() {
193:         if let Some(t) = top {
194:             if !t.ok {
195:                 top_reason = t.reason.clone();
196:             }
197:         }
198:     }
199:     if !file_reason.is_empty() {
200:         notes.push(file_reason.clone());
201:     }
202:     if let Some(t) = top {
203:         let pf = config::get_toml_string(Some(t), "profile");
204:         if pf.present {
205:             if !pf.reason.is_empty() {
206:                 notes.push(pf.reason);
207:             } else {
208:                 notes.push(format!(
209:                     "the Codex config selects profile '{}' (line {}); profiles are not supported - a profile can change the provider, the model and the effort behind the bridge",
210:                     pf.value, pf.line
211:                 ));
212:             }
213:         }
214:     }
215:     let cfg_provider = if top.is_some() && top_reason.is_empty() {
216:         Some(config::get_toml_string(top, "model_provider"))
217:     } else {
218:         None
219:     };
220:     let cfg_model = if top.is_some() && top_reason.is_empty() {
221:         Some(config::get_toml_string(top, "model"))
222:     } else {
223:         None
224:     };
225: 
226:     if !provider.is_empty() {
227:         id.provider = provider.to_string();
228:         id.provider_source = "-Provider".into();
229:     } else if !top_reason.is_empty() {
230:         if !notes.contains(&top_reason) {
231:             notes.push(top_reason.clone());
232:         }
233:     } else if let Some(cp) = &cfg_provider {
234:         if cp.present {
235:             if !cp.reason.is_empty() {
236:                 notes.push(cp.reason.clone());
237:             } else if cp.value.is_empty() {
238:                 notes.push(format!(
239:                     "model_provider at line {} of {where_} is empty",
240:                     cp.line
241:                 ));
242:             } else {
243:                 id.provider = cp.value.clone();
244:                 id.provider_source = "config".into();
245:             }
246:         } else {
247:             id.provider = "openai".into();
248:             id.provider_source = "codex default".into();
249:         }
250:     } else {
251:         id.provider = "openai".into();
252:         id.provider_source = "codex default".into();
253:     }
254: 
255:     if !model.is_empty() {
256:         id.model = model.to_string();
257:         id.model_source = "-Model".into();
258:     } else if !top_reason.is_empty() {
259:         if !notes.contains(&top_reason) {
260:             notes.push(top_reason.clone());
261:         }
262:     } else if let Some(cm) = &cfg_model {
263:         if cm.present {
264:             if !cm.reason.is_empty() {
265:                 notes.push(cm.reason.clone());
266:             } else if cm.value.is_empty() {
267:                 notes.push(format!("model at line {} of {where_} is empty", cm.line));
268:             } else {
269:                 id.model = cm.value.clone();
270:                 id.model_source = "config".into();
271:             }
272:         } else if config.exists {
273:             notes.push(format!("no -Model and no top-level model in {where_}"));
274:         } else {
275:             notes.push(format!("no -Model and no Codex config at {where_} (the model Codex picks by default is not known to the bridge)"));
276:         }
277:     } else if config.exists {
278:         notes.push(format!("no -Model and no top-level model in {where_}"));
279:     } else {
280:         notes.push(format!("no -Model and no Codex config at {where_} (the model Codex picks by default is not known to the bridge)"));
281:     }
282: 
283:     let mut compat = String::new();
284:     if !id.provider_source.is_empty() {
285:         let name = id.provider.clone();
286:         let table_name = format!(
287:             "[{}]",
288:             config::format_toml_path(&["model_providers".into(), name.clone()])
289:         );
290:         let mut err = String::new();
291:         let (pt_found, pt_ok, pt_reason, pt_key) = if config.exists && config.ok {
292:             let pt = provider_table(config, &name);
293:             (pt.found, pt.ok, pt.reason, pt.table_key)
294:         } else {
295:             (false, false, String::new(), None)
296:         };
297:         let set_problem = if config.exists && config.ok {
298:             provider_set_problem(config, &name)
299:         } else {
300:             String::new()
301:         };
302:         if !set_problem.is_empty() {
303:             err = format!("the providers in {where_} could not be established, so {table_name} may be declared there - {set_problem}");
304:         } else if name == "openai" && !pt_found {
305:             compat = "cc-provider-v1|builtin:openai".into();
306:             id.host = "builtin:openai".into();
307:             id.wire_api = "(built in)".into();
308:             if !openai_base_url.trim().is_empty() {
309:                 let (curl, chost) = canonical_base_url(openai_base_url);
310:                 compat.push_str(&format!("|base_url={curl}"));
311:                 id.host = chost;
312:                 id.base_url = curl;
313:             }
314:         } else if !config.exists {
315:             err = format!("unknown provider '{name}': there is no Codex config at {where_}, so there is no {table_name} table (built in: openai)");
316:         } else if !config.ok {
317:             err = format!("{table_name} cannot be read: {}", config.reason);
318:         } else if !pt_found {
319:             let found = provider_names(config);
320:             let list = if found.is_empty() {
321:                 "(none)".to_string()
322:             } else {
323:                 found.join(", ")
324:             };
325:             err = format!("unknown provider '{name}': {where_} has no {table_name} table; providers found: {list} (built in: openai)");
326:         } else if !pt_ok {
327:             err = format!("{table_name} in {where_} is not usable - {pt_reason}");
328:         } else {
329:             let ep = provider_endpoint(
330:                 config,
331:                 pt_key.as_deref().unwrap_or(""),
332:                 &table_name,
333:                 &where_,
334:             );
335:             if !ep.error.is_empty() {
336:                 err = ep.error;
337:             } else {
338:                 compat = ep.compat;
339:                 id.host = ep.host;
340:                 id.base_url = ep.base_url;
341:                 id.wire_api = ep.wire_api;
342:                 if name == "openai" {
343:                     infos.push(
344:                         "user-defined [model_providers.openai] table used for the identity".into(),
345:                     );
346:                 }
347:             }
348:         }
349:         if !err.is_empty() {
350:             if id.provider_source == "-Provider" {
351:                 id.error = err.clone();
352:             } else if name == "openai" {
353:                 let who = if id.provider_source == "config" {
354:                     "the config's model_provider"
355:                 } else {
356:                     "Codex's default provider openai"
357:                 };
358:                 notes.push(format!("{who}: {err}"));
359:             } else {
360:                 notes.push(format!("the config's model_provider: {err}"));
361:             }
362:             compat.clear();
363:         }
364:     }
365:     id.lineage = format_lineage(&id.provider, &id.model);
366:     id.resolved = !id.provider_source.is_empty()
367:         && id.model_source != "unknown"
368:         && !compat.is_empty()
369:         && id.error.is_empty()
370:         && notes.is_empty();
371:     if id.resolved {
372:         id.compat_string = compat.clone();
373:         id.fingerprint = sha256_hex(compat.as_bytes());
374:     }
375:     let mut all = notes;
376:     all.extend(infos);
377:     id.note = all.join("; ");
378:     id
379: }
