381: fn resolve_engine_identity(
382:     mut id: ReviewerIdentity,
383:     engine: &str,
384:     provider: &str,
385:     model: &str,
386:     launcher: &str,
387: ) -> ReviewerIdentity {
388:     id.engine = engine.to_string();
389:     let spec = match engine_spec(engine) {
390:         Some(s) => s,
391:         None => {
392:             id.error = format!(
393:                 "unknown engine '{engine}' (engines: {})",
394:                 ENGINE_NAMES.join(", ")
395:             );
396:             id.lineage = format_lineage(&id.provider, &id.model);
397:             return id;
398:         }
399:     };
400:     if !provider.is_empty() {
401:         id.provider = provider.to_string();
402:         id.provider_source = "-Provider".into();
403:     } else {
404:         id.provider = spec.default_provider.to_string();
405:         id.provider_source = "engine default".into();
406:     }
407:     if !model.is_empty() {
408:         id.model = model.to_string();
409:         id.model_source = "-Model".into();
410:     } else {
411:         id.error = format!(
412:             "the {engine} engine needs a model: pass -Model <id> (the full model id, e.g. {}) or name it in the roster entry",
413:             spec.model_example
414:         );
415:     }
416:     id.host = spec.host_name.to_string();
417:     id.wire_api = String::new();
418:     id.base_url = String::new();
419:     id.lineage = format_lineage(&id.provider, &id.model);
420:     let _ = launcher;
421:     if id.error.is_empty() {
422:         id.resolved = true;
423:         id.compat_string = spec.compat_string.to_string();
424:         id.fingerprint = sha256_hex(spec.compat_string.as_bytes());
425:     }
426:     id
427: }

